def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    opp_coop = n - opp_d
    my_coop = n - my_d
    opp_rate = opp_coop / n
    my_rate = my_coop / n

    w = 15 if n > 15 else n
    rec_od = 0
    for m, o in history[-w:]:
        if o == 'D':
            rec_od += 1

    tail_od = 0
    for m, o in reversed(history):
        if o == 'D':
            tail_od += 1
        else:
            break

    tail_oc = 0
    for m, o in reversed(history):
        if o == 'C':
            tail_oc += 1
        else:
            break

    tail_cd = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'D':
            tail_cd += 1
        else:
            break

    mutual_d = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            mutual_d += 1
        else:
            break

    s_start = n - 8
    if s_start < 1:
        s_start = 1

    unpun = 0
    pun = 0
    for i in range(s_start, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                unpun += 1
            else:
                pun += 1

    soft = (
        unpun > 0
        and pun == 0
        and opp_rate > 0.65
        and rec_od <= 2
        and tail_oc >= 1
    )

    if last_opp == 'D':
        if last_me == 'D':
            if mutual_d >= 6:
                return 'C'
            if opp_rate > 0.5 and tail_od <= 2 and rec_od <= 4:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if tail_cd <= 2 and opp_rate > 0.7 and rec_od <= 4:
                return 'C'
            if tail_cd <= 1 and opp_coop > 0 and opp_rate > 0.08:
                return 'C'
            if tail_od <= 1 and opp_rate > 0.2:
                return 'C'
            return 'D'

        if tail_od >= 2 or rec_od >= 4 or opp_rate < 0.55:
            return 'D'
        return 'D'

    if last_me == 'D':
        if soft:
            return 'D'
        return 'C'

    if soft:
        return 'D'

    if (
        n >= 18
        and n % 18 == 0
        and opp_rate > 0.65
        and my_rate > 0.65
        and rec_od <= 2
        and tail_oc >= 5
    ):
        return 'D'

    if opp_rate < 0.35 and rec_od >= 6:
        return 'D'

    return 'C'
